#!/usr/bin/env python3
"""Generates engine/model/{quant,unicode}_tables.h from the pinned llama.cpp sources (MIT).

Usage: tools/gen_tables.py [LLAMA_CPP_SRC]   (default: work/src/llama.cpp, see scripts/build-llamacpp.sh)
"""

import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
HEAD = """// {what}, taken unchanged from llama.cpp b11822
// ({src}).
// llama.cpp/ggml: MIT license, Copyright (c) 2023-2026 The ggml authors.
// Generated by tools/gen_tables.py; do not edit, regenerate instead.
#pragma once

#include <cstdint>
"""


def numbers(body: str) -> list[str]:
    return re.findall(r"-?0x[0-9a-fA-F]+|-?\d+", re.sub(r"//[^\n]*", "", body))


def quant(src: Path) -> str:
    text = (src / "ggml/src/ggml-common.h").read_text()
    out = [
        HEAD.format(what="Lookup tables of the IQ formats", src="ggml/src/ggml-common.h"),
        "namespace tona::tables {",
        "",
    ]
    for ctype, name, n in [
        ("uint8_t", "kmask_iq2xs", 8),
        ("uint8_t", "ksigns_iq2xs", 128),
        ("uint64_t", "iq2xxs_grid", 256),
        ("uint64_t", "iq2s_grid", 1024),
        ("uint32_t", "iq3xxs_grid", 256),
        ("uint32_t", "iq3s_grid", 512),
        ("int8_t", "kvalues_iq4nl", 16),
    ]:
        m = re.search(rf"GGML_TABLE_BEGIN\({ctype},\s*{name},\s*{n}\)(.*?)GGML_TABLE_END\(\)", text, re.S)
        vals = numbers(m.group(1))
        assert len(vals) == n, (name, len(vals))
        out.append(f"inline constexpr {ctype} {name}[{n}] = {{")
        out += ["    " + ", ".join(vals[i : i + 8]) + "," for i in range(0, n, 8)]
        out.append("};\n")
    out.append("}  // namespace tona::tables")
    return "\n".join(out) + "\n"


def unicode(src: Path) -> str:
    text = (src / "src/unicode-data.cpp").read_text()
    m = re.search(r"unicode_ranges_flags = \{[^\n]*\n(.*?)\n\};", text, re.S)
    pairs = re.findall(r"\{(0x[0-9A-Fa-f]+), (0x[0-9A-Fa-f]+)\}", m.group(1))
    assert int(pairs[0][0], 16) == 0 and int(pairs[-1][0], 16) == 0x110000, "range bounds"
    m = re.search(r"unicode_set_whitespace = \{(.*?)\};", text, re.S)
    ws = numbers(m.group(1))
    out = [
        HEAD.format(what="Unicode categories (category bits only) and whitespace", src="src/unicode-data.cpp"),
        "namespace tona::tables {",
        "",
        "// Bits as in unicode_cpt_flags: 1 undefined, 2 \\p{N}, 4 \\p{L}, 8 \\p{Z}, 0x10 \\p{M}, 0x20 \\p{P},",
        "// 0x40 \\p{S}, 0x80 \\p{C}. Range i spans start[i] to start[i+1]-1; the last entry is 0x110000.",
        f"inline constexpr uint32_t unicode_range_start[{len(pairs)}] = {{",
    ]
    out += ["    " + ", ".join(p[0] for p in pairs[i : i + 10]) + "," for i in range(0, len(pairs), 10)]
    out += ["};", f"inline constexpr uint8_t unicode_range_flags[{len(pairs)}] = {{"]
    out += [
        "    " + ", ".join(hex(int(p[1], 16) & 0xFF) for p in pairs[i : i + 16]) + "," for i in range(0, len(pairs), 16)
    ]
    out += [
        "};",
        "",
        f"inline constexpr uint32_t unicode_whitespace[{len(ws)}] = {{",
        "    " + ", ".join(ws) + ",",
        "};",
        "",
        "}  // namespace tona::tables",
    ]
    return "\n".join(out) + "\n"


def main() -> int:
    src = Path(sys.argv[1]) if len(sys.argv) > 1 else ROOT / "work/src/llama.cpp"
    for name, fn in [("quant_tables.h", quant), ("unicode_tables.h", unicode)]:
        p = ROOT / "engine/model" / name
        p.write_text(fn(src))
        print(p.relative_to(ROOT))
    return 0


if __name__ == "__main__":
    sys.exit(main())
